extern S_SYSTEM_DATA *myData;
extern S_MODULE_DATA *myPs;
extern S_CH_DATA *myCh;
extern S_TEST_CONDITION *myTestCond;

void Output_Ch_Switch(int slot)
{
	int ch;

	switch(myPs->misc.module_type) {
		case MODULE_LINEAR:
			for(ch=0; ch < myPs->config.installedCh; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				Output_Ch_Switch_General(slot, ch);
			}
			break;
		case MODULE_PWM1:
			for(ch=0; ch < myPs->config.installedCh; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				Output_Ch_Switch_Pack(slot, ch);
			}
			break;
		case MODULE_FCH:
			break;
		case MODULE_PWM2:
			for(ch=0; ch < myPs->config.installedCh; ch++) {
				myCh = &(myData->cData[ch]);
				if(set_testCond_point(ch) < 0) continue;

				Output_Ch_Switch_PWM2(slot, ch);
			}
			break;
		case MODULE_PWM3:
			break;
		default:
			break;
	}
}

void Output_Ch_Switch_General(int slot, int ch)
{
	switch(myCh->signal[C_SIG_OUT_SWITCH]) {
		case P1: //semi switch off, relay off (slow)
			cOutSwitch_P1_General1(ch, slot);
			break;
		case P11: //semi switch off (slow)
			cOutSwitch_P11_General1(ch, slot);
			break;
		case P21: //semi switch off (fast)
			cOutSwitch_P21_General1(ch, slot);
			break;
		case P51: //relay on, semi switch on (slow) for calibration
			cOutSwitch_P51_General1(ch, slot);
			break;
		case P61: //semi switch on (slow) for calibration
			cOutSwitch_P61_General1(ch, slot);
			break;
		case P71: //relay on, semi switch on (fast)
			cOutSwitch_P71_General_N1(ch, slot); //kjg_120326
			break;
		case P81: //semi switch on (user pattern)
			switch(myData->AppControl.config.systemModel) {
				case C_SDI_70V_50A_5A_4KW:
				case C_SDI_70V_50A_5A_4KW_2:
				case C_SDI_70V_50A_5A_7KW:
				case C_SDI_70V_50A_5A_7KW_2:
					cOutSwitch_P81_General2(ch, slot);
					break;
				case C_SDI_70V_250A_25A_18KW:
					cOutSwitch_P81_General3(ch, slot);
					break;
				default:
					cOutSwitch_P81_General1(ch, slot);
					break;
			}
			break;
		case P85: //semi switch on (user pattern2)
			cOutSwitch_P85_General_N1(ch, slot); //kjg_120326
			break;
		case P91: //semi switch on (external can)
			cOutSwitch_P91_General1(ch, slot);
			break;
		case P95: //semi switch on (external can)
			cOutSwitch_P95_General1(ch, slot);
			break;
		default:
			break;
	}
}

