void cOutSwitch_Select_rangeI(int ch, int rangeI)
{
	int group=0;

	switch(myData->AppControl.config.systemModel) {
		case F_SDI_5V_200A_100A_50A_10A:			//csk_161013
		case F_SBL_5V_250A_125A_65A_10A:
		case F_SDI_5V_400A_200A_100A_10A:
		case F_SDI_5V_400A_200A_100A_10A_2:
		case F_SDI_5V_450A_200A_100A_10A:
		case F_SDI_5V_450A_200A_100A_10A_2:
			switch(rangeI+1) {
				case RANGE1:
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE3, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE4, OFF);
					break;
				case RANGE2:
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, ON);
					Select_OutPoint(group, ch+1, O_I_RANGE3, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE4, OFF);
					break;
				case RANGE3:
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, ON);
					Select_OutPoint(group, ch+1, O_I_RANGE3, ON);
					Select_OutPoint(group, ch+1, O_I_RANGE4, OFF);
					break;
				default: //RANGE4
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE3, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE4, ON);
					break;
			}
			break;
		default:
			switch(rangeI+1) {
				case RANGE1:
					Select_OutPoint(group, ch+1, O_I_RANGE1, ON);
					Select_OutPoint(group, ch+1, O_I_RANGE2, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE3, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE4, OFF);
					break;
				case RANGE2:
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, ON);
					Select_OutPoint(group, ch+1, O_I_RANGE3, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE4, OFF);
					break;
				case RANGE3:
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE3, ON);
					Select_OutPoint(group, ch+1, O_I_RANGE4, OFF);
					break;
				default: //RANGE4
					Select_OutPoint(group, ch+1, O_I_RANGE1, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE2, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE3, OFF);
					Select_OutPoint(group, ch+1, O_I_RANGE4, ON);
					break;
			}
			break;
	}
}

