		case C_SKI_50V_500A_400A_200A_100A_100KW_2:	//jhk_180119
		case C_KTL_60V_400A_200A_40KW:	//jhk_181218
		case C_NORTHVOLT_60V_400A_200A_96KW:	//khj_191203
		case C_KTL_60V_400A_200A_100A_60KW:		//sec_230912
