		case C_ENERTECH_55V_100A_10A:
			//AMP -> AD620A
			//G = (49.4k / 18k) + 1 = 3.744444444
			//V1 = 2.5V * G = 9361111.11uV
			//1LSB = V1 / 32768 = 285.6784396uV
