long cal_internal_dv(int ch, long ocv, long cmd_i, long internal_r)
{
	long cmd_p;
	double dv, dv2, rtn_cmd_i;

	cmd_p = myData->cData[ch].misc.cmd_p[0];
	dv2 = (double)internal_r * myData->cData[ch].ccv[0].avg_i / 1000000.0;

	dv = (double)internal_r * (double)cmd_i / 1000000.0;
	rtn_cmd_i = (double)cmd_p / ((double)ocv + dv - dv2);

	if(cmd_i >= 0) {
		rtn_cmd_i *= 1000000000.0;
	} else {
		rtn_cmd_i *= (-1000000000.0);
	}

	if(rtn_cmd_i > myPs->config.maxI[0]) rtn_cmd_i = myPs->config.maxI[0];		//csk_200207_packMerge
	else if(rtn_cmd_i < myPs->config.minI[0]) rtn_cmd_i = myPs->config.minI[0];	//csk_200207_packMerge

	return (long)rtn_cmd_i;
}

long cal_internal_dv2(int ch, long ocv, long cmd_i, long internal_r)
{
	long cmd_p;
	double dv, rtn_cmd_i;

	cmd_p = myData->cData[ch].misc.cmd_p[0];

	dv = (double)internal_r
		* ((double)cmd_i - (double)myData->cData[ch].misc.tmpIsens) / 1000000.0;
	if(cmd_i >= 0) dv *= (-1.0);
	rtn_cmd_i = (double)cmd_p / ((double)ocv + dv);

	if(cmd_i >= 0) {
		rtn_cmd_i *= 1000000000.0;
	} else {
		rtn_cmd_i *= (-1000000000.0);
	}

	if(rtn_cmd_i > myPs->config.maxI[0]) rtn_cmd_i = myPs->config.maxI[0];		//csk_200207_packMerge
	else if(rtn_cmd_i < myPs->config.minI[0]) rtn_cmd_i = myPs->config.minI[0];	//csk_200207_packMerge

	return (long)rtn_cmd_i;
}

void calculate_DCR_2(int ch, int v_type)
{
	int i, val1, val2;
	double tmp, sumT, avgT, sumV, avgV, sumT2, mul_sumT2, sumTV, mul_sumTV;
	double tmp_a, tmp_b;

	sumT = 0.0; sumV = 0.0; sumT2 = 0.0; sumTV = 0.0;
	if(v_type == 0) {
		val1 = myData->cData[ch].misc.d_count - (int)myPs->config.dcr_count1;
		if(val1 < 0) val1 = 0;
		val2 = myData->cData[ch].misc.d_count;
	} else {
		val1 = (int)myPs->config.dcr_t2 / 10;
		val2 = val1 + (int)myPs->config.dcr_count2;
	}
	for(i=val1; i < val2; i++) {
		sumT += (double)myData->cData[ch].misc.d_t[i] / 100.0;
		sumV += (double)myData->cData[ch].misc.d_v[i] / 1000.0;
		sumT2 += ((double)myData->cData[ch].misc.d_t[i] / 100.0)
			* ((double)myData->cData[ch].misc.d_t[i] / 100.0);
		sumTV += ((double)myData->cData[ch].misc.d_t[i] / 100.0)
			* ((double)myData->cData[ch].misc.d_v[i] / 1000.0);
	}

	if(v_type == 0) {
		tmp = (double)myPs->config.dcr_count1;
	} else {
		tmp = (double)myPs->config.dcr_count2;
	}
	avgT = sumT / tmp;
	avgV = sumV / tmp;
	mul_sumT2 = sumT2 * tmp;
	mul_sumTV = sumTV * tmp;
	tmp = mul_sumT2 - sumT * sumT;
	if(tmp != 0.0) {
		tmp_a = (mul_sumTV - sumT * sumV) / tmp;
		tmp_b = (avgV - tmp_a * avgT) * 1000.0;
		if(v_type == 0) {
			i = (int)myPs->config.dcr_count1 - 1;
			myData->cData[ch].ccv[1].avg_v
				= (long)(tmp_a * myData->cData[ch].misc.d_t[i] + tmp_b);

			sumT = 0.0;
			for(i=val1; i < val2; i++) {
				sumT += (double)myData->cData[ch].misc.d_i[i];
			}
			sumT /= (double)myPs->config.dcr_count1;
			myData->cData[ch].ccv[1].avg_i = (long)sumT;
		} else {
			i = 0;
			myData->cData[ch].misc.d_voltage
				= (long)(tmp_a * myData->cData[ch].misc.d_t[i] + tmp_b);
		}
	} else {
		if(v_type == 0) {
			myData->cData[ch].ccv[1].avg_v = 0;
			myData->cData[ch].ccv[1].avg_i = 0;
		} else {
			myData->cData[ch].misc.d_voltage = 0;
		}
	}

	if(v_type == 0) return;

	val1 = myData->cData[ch].ccv[1].avg_v;
	val2 = myData->cData[ch].misc.d_voltage;
	if(val1 >= 0 && val2 >= 0) {
		val1 = val1 - val2;
	} else if(val1 >= 0 && val2 < 0) {
		val1 = val1 - val2;
	} else if(val1 < 0 && val2 >= 0) {
		val1 = val1 * (-1) + val2;
	} else {
		val1 = val1 - val2;
	}
	if(val1 < 0) val1 *= (-1);
	avgV = (double)val1;

	sumT = 0.0;
	val1 = (int)myPs->config.dcr_t2 / 10;
	val2 = val1 + (int)myPs->config.dcr_count2;
	for(i=val1; i < val2; i++) {
		sumT += (double)myData->cData[ch].misc.d_i[i];
	}
	val1 = (long)(sumT / (double)myPs->config.dcr_count2);
	val2 = val1 - myData->cData[ch].ccv[1].avg_i;
	if(val2 < 0) val2 *= (-1);
	if(val2 != 0) {
		tmp = avgV / (double)val2;
		myData->cData[ch].op.z = (long)(tmp * 1000000.0);
	} else {
		myData->cData[ch].op.z = 0;
	}
}

int find_master_ch(int ch)
{ //kjg_111022
	int master_ch, i, j, k;

	if(myData->ChAttribute[ch].chNo_master > 0) { //master
		master_ch = ch;
	} else { //slave
		master_ch = (-1);
		for(i=ch; i >= 0; i--) {
			k = (-1);
			for(j=0; j < MAX_SLAVE_CH; j++) {
				k = (int)myData->ChAttribute[i].chNo_slave[j] - 1;
				if(ch == k) {
					master_ch = (int)myData->ChAttribute[i].chNo_master - 1;
					break;
				}
			}
			if(k >= 0) break;
		}
	}

	return master_ch;
}

